        if x > _exit_x_min(sandbox) + 2.5:
            state["phase"] = "HOLD"
    elif state["phase"] == "HOLD":
        fx, fy = 0.0, 0.0

    # Calculate impulse and check structural limit
    impulse = fx * dt
    state["total_impulse"] += impulse
    if state["total_impulse"] > 60.0:
        # Destroy the robot
        return

    sandbox.apply_agent_force(fx, fy)
